package com.club.service;
import com.club.dto.*; import com.club.entity.GrupoFamiliar; import com.club.enumeration.*; import com.club.exception.BusinessException; import com.club.repository.*; import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.util.Optional; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
class PagoServiceTest { @Test void registraEfectivo(){var fr=mock(GrupoFamiliarRepository.class);var pr=mock(PagoRepository.class);var f=new GrupoFamiliar();f.setId("f");when(fr.findById("f")).thenReturn(Optional.of(f));when(pr.existsByGrupoFamiliarIdAndPeriodo("f","2026-09")).thenReturn(false);when(pr.save(any())).thenAnswer(i->i.getArgument(0));PagoResponse p=new PagoService(fr,pr).registrarPago("f",new RegistrarPagoDTO("2026-09",new BigDecimal("25000"),MedioPago.EFECTIVO,null));assertEquals(EstadoPago.REGISTRADO,p.estado());} @Test void transferenciaRequiereReferencia(){var fr=mock(GrupoFamiliarRepository.class);var pr=mock(PagoRepository.class);when(fr.findById("f")).thenReturn(Optional.of(new GrupoFamiliar()));when(pr.existsByGrupoFamiliarIdAndPeriodo("f","2026-09")).thenReturn(false);assertThrows(BusinessException.class,()->new PagoService(fr,pr).registrarPago("f",new RegistrarPagoDTO("2026-09",new BigDecimal("1"),MedioPago.TRANSFERENCIA,null)));} @Test void duplicado(){var fr=mock(GrupoFamiliarRepository.class);var pr=mock(PagoRepository.class);when(fr.findById("f")).thenReturn(Optional.of(new GrupoFamiliar()));when(pr.existsByGrupoFamiliarIdAndPeriodo("f","2026-09")).thenReturn(true);assertThrows(BusinessException.class,()->new PagoService(fr,pr).registrarPago("f",new RegistrarPagoDTO("2026-09",BigDecimal.ONE,MedioPago.EFECTIVO,null)));}}
